<body>
<div id="app">
    <header>
        <div class="header-left">
            <div class="logo-icon">✦</div>
            <h1>GLM Chat</h1>
            <button id="toggle-system-btn" title="Rendszer-prompt beállítása">⚙ Rendszer-prompt</button>
        </div>
        <div class="header-right">
            <div class="model-select-wrapper">
                <select id="model-select">
                    <option value="glm-4-plus">GLM-4 Plus</option>
                    <option value="glm-4">GLM-4</option>
                    <option value="glm-4-air">GLM-4 Air</option>
                    <option value="glm-4-flash">GLM-4 Flash</option>
                </select>
                <span class="model-select-arrow">▾</span>
            </div>
            <button id="clear-btn">Törlés</button>
        </div>
    </header>

    <div id="system-prompt-section" class="collapsed">
        <div class="system-prompt-inner">
            <span class="system-prompt-label">Rendszer-prompt</span>
            <textarea id="system-prompt-input" rows="2" placeholder="Pl.: Te egy hasznos asszisztens vagy. Magyarul válaszolj.">Te egy hasznos AI asszisztens vagy. Mindig magyarul válaszolj, ha a felhasználó magyarul ír hozzád.</textarea>
        </div>
    </div>

    <div id="chat-window">
        <div class="welcome-msg" id="welcome-msg">
            <div class="welcome-icon">✦</div>
            <p>Kezdj el chattelni a GLM modellel. A rendszer-prompt szerkesztéséhez kattints a ⚙ gombra.</p>
        </div>
    </div>

    <div id="input-area">
        <div class="input-container">
            <textarea
                id="user-input"
                placeholder="Írj üzenetet..."
                rows="1"
            ></textarea>
            <div class="input-actions">
                <button id="stop-btn" title="Generálás leállítása">⏹</button>
                <button id="send-btn" title="Küldés (Enter)">▶</button>
            </div>
        </div>
        <div class="input-hint">Enter = küldés &nbsp;·&nbsp; Shift+Enter = új sor</div>
    </div>
</div>

<script>
    const chatWindow = document.getElementById('chat-window');
    const userInput = document.getElementById('user-input');
    const sendBtn = document.getElementById('send-btn');
    const stopBtn = document.getElementById('stop-btn');
    const clearBtn = document.getElementById('clear-btn');
    const modelSelect = document.getElementById('model-select');
    const systemPromptInput = document.getElementById('system-prompt-input');
    const systemPromptSection = document.getElementById('system-prompt-section');
    const toggleSystemBtn = document.getElementById('toggle-system-btn');
    const welcomeMsg = document.getElementById('welcome-msg');

    let conversationHistory = [];
    let currentAbortController = null;
    let isStreaming = false;
    let systemPromptVisible = false;

    function removeWelcome() {
        if (welcomeMsg && welcomeMsg.parentNode) {
            welcomeMsg.parentNode.removeChild(welcomeMsg);
        }
    }

    function formatTime(date) {
        return date.toLocaleTimeString('hu-HU', { hour: '2-digit', minute: '2-digit' });
    }

    function createTypingIndicator() {
        const row = document.createElement('div');
        row.className = 'message-row assistant';
        row.id = 'typing-indicator-row';
        const indicator = document.createElement('div');
        indicator.className = 'typing-indicator';
        for (let i = 0; i < 3; i++) {
            const dot = document.createElement('div');
            dot.className = 'typing-dot';
            indicator.appendChild(dot);
        }
        row.appendChild(indicator);
        chatWindow.appendChild(row);
        chatWindow.scrollTop = chatWindow.scrollHeight;
        return row;
    }

    function removeTypingIndicator() {
        const el = document.getElementById('typing-indicator-row');
        if (el) el.remove();
    }

    function createAssistantBubble() {
        const row = document.createElement('div');
        row.className = 'message-row assistant';

        const label = document.createElement('div');
        label.className = 'message-role-label';
        label.textContent = 'GLM';

        const bubble = document.createElement('div');
        bubble.className = 'message-bubble';

        const cursor = document.createElement('span');
        cursor.className = 'cursor-blink';
        cursor.id = 'stream-cursor';

        bubble.appendChild(cursor);
        row.appendChild(label);
        row.appendChild(bubble);
        chatWindow.appendChild(row);
        chatWindow.scrollTop = chatWindow.scrollHeight;

        return { row, bubble, cursor };
    }

    function appendUserMessage(text) {
        removeWelcome();

        const row = document.createElement('div');
        row.className = 'message-row user';

        const label = document.createElement('div');
        label.className = 'message-role-label';
        label.textContent = 'Te';

        const bubble = document.createElement('div');
        bubble.className = 'message-bubble';
        bubble.textContent = text;

        const meta = document.createElement('div');
        meta.className = 'message-meta';
        meta.textContent = formatTime(new Date());

        row.appendChild(label);
        row.appendChild(bubble);
        row.appendChild(meta);
        chatWindow.appendChild(row);
        chatWindow.scrollTop = chatWindow.scrollHeight;
    }

    function appendErrorMessage(text) {
        const row = document.createElement('div');
        row.className = 'message-row error';

        const bubble = document.createElement('div');
        bubble.className = 'message-bubble';
        bubble.textContent = '❌ ' + text;

        row.appendChild(bubble);
        chatWindow.appendChild(row);
        chatWindow.scrollTop = chatWindow.scrollHeight;
    }

    function setStreamingState(streaming) {
        isStreaming = streaming;
        sendBtn.disabled = streaming;
        userInput.disabled = streaming;
        if (streaming) {
            stopBtn.classList.add('visible');
        } else {
            stopBtn.classList.remove('visible');
        }
    }

    async function sendMessage() {
        const text = userInput.value.trim();
        if (!text || isStreaming) return;

        appendUserMessage(text);

        const systemContent = systemPromptInput.value.trim();
        const messagesPayload = [];
        if (systemContent) {
            messagesPayload.push({ role: 'system', content: systemContent });
        }
        conversationHistory.forEach(m => messagesPayload.push(m));
        messagesPayload.push({ role: 'user', content: text });

        conversationHistory.push({ role: 'user', content: text });

        userInput.value = '';
        userInput.style.height = 'auto';

        setStreamingState(true);

        const typingRow = createTypingIndicator();

        currentAbortController = new AbortController();

        let fullResponse = '';
        let assistantElements = null;

        try {
            const response = await fetch('/api/chat', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    messages: messagesPayload,
                    model: modelSelect.value,
                    max_tokens: 4096,
                    temperature: 0.7,
                }),
                signal: currentAbortController.signal,
            });

            if (!response.ok) {
                const errText = await response.text();
                throw new Error(`HTTP ${response.status}: ${errText}`);
            }

            removeTypingIndicator();
            assistantElements = createAssistantBubble();

            const reader = response.body.getReader();
            const decoder = new TextDecoder('utf-8');
            let buffer = '';

            while (true) {
                const { done, value } = await reader.read();
                if (done) break;

                buffer += decoder.decode(value, { stream: true });
                const lines = buffer.split('\n');
                buffer = lines.pop();

                for (const line of lines) {
                    const trimmed = line.trim();
                    if (!trimmed.startsWith('data: ')) continue;
                    const raw = trimmed.slice(6);
                    if (!raw) continue;

                    let parsed;
                    try {
                        parsed = JSON.parse(raw);
                    } catch (_) {
                        continue;
                    }

                    if (parsed.error) {
                        throw new Error(parsed.error);
                    }

                    if (parsed.content) {
                        fullResponse += parsed.content;
                        const textNode = document.createTextNode('');
                        assistantElements.bubble.insertBefore(textNode, assistantElements.cursor);
                        assistantElements.bubble.childNodes[assistantElements.bubble.childNodes.length - 2].textContent = fullResponse;
                        chatWindow.scrollTop = chatWindow.scrollHeight;
                    }

                    if (parsed.done) {
                        break;
                    }
                }
            }

            if (assistantElements && assistantElements.cursor) {
                assistantElements.cursor.remove();
            }

            const meta = document.createElement('div');
            meta.className = 'message-meta';
            meta.textContent = formatTime(new Date()) + '  ·  ' + fullResponse.length + ' karakter';
            if (assistantElements) {
                assistantElements.row.appendChild(meta);
            }

            if (fullResponse) {
                conversationHistory.push({ role: 'assistant', content: fullResponse });
            }

        } catch (err) {
            removeTypingIndicator();
            if (assistantElements && assistantElements.cursor) {
                assistantElements.cursor.remove();
            }
            if (err.name !== 'AbortError') {
                appendErrorMessage(err.message);
            } else {
                if (assistantElements && fullResponse) {
                    const meta = document.createElement('div');
                    meta.className = 'message-meta';
                    meta.textContent = formatTime(new Date()) + '  ·  leállítva';
                    assistantElements.row.appendChild(meta);
                    conversationHistory.push({ role: 'assistant', content: fullResponse });
                }
            }
        } finally {
            setStreamingState(false);
            currentAbortController = null;
            chatWindow.scrollTop = chatWindow.scrollHeight;
        }
    }

    function stopGeneration() {
        if (currentAbortController) {
            currentAbortController.abort();
        }
    }

    function clearConversation() {
        conversationHistory = [];
        chatWindow.innerHTML = '';
        const welcome = document.createElement('div');
        welcome.className = 'welcome-msg';
        welcome.id = 'welcome-msg';
        welcome.innerHTML = '<div class="welcome-icon">✦</div><p>A beszélgetés törölve. Kezdhetsz újat!</p>';
        chatWindow.appendChild(welcome);
    }

    function toggleSystemPrompt() {
        systemPromptVisible = !systemPromptVisible;
        if (systemPromptVisible) {
            systemPromptSection.classList.remove('collapsed');
            systemPromptSection.classList.add('expanded');
            toggleSystemBtn.style.color = 'var(--accent)';
            toggleSystemBtn.style.borderColor = 'var(--accent)';
        } else {
            systemPromptSection.classList.remove('expanded');
            systemPromptSection.classList.add('collapsed');
            toggleSystemBtn.style.color = '';
            toggleSystemBtn.style.borderColor = '';
        }
    }

    userInput.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            sendMessage();
        }
    });

    userInput.addEventListener('input', () => {
        userInput.style.height = 'auto';
        userInput.style.height = Math.min(userInput.scrollHeight, 220) + 'px';
    });

    sendBtn.addEventListener('click', sendMessage);
    stopBtn.addEventListener('click', stopGeneration);
    clearBtn.addEventListener('click', clearConversation);
    toggleSystemBtn.addEventListener('click', toggleSystemPrompt);

    fetch('/api/models')
        .then(r => r.json())
        .then(data => {
            modelSelect.innerHTML = '';
            data.models.forEach(m => {
                const opt = document.createElement('option');
                opt.value = m.id;
                opt.textContent = m.name + ' (' + m.context + ')';
                modelSelect.appendChild(opt);
            });
        })
        .catch(() => {});
</script>
</body>
</html>




